from audit_utils import *

for tree,layer in [('fr_printed','French as printed'),('fr','French corrected')]:
 rel=f'sources/{tree}/fr/195.tex'
 def r(a,b,line,kind='reading',why='',count=1):
  replace(rel,a,b,layer,'195-384',line,'C.3','400-dpi full scan and all three enlarged bands. '+why,kind,count=count)
 s,_,_=page_text(rel,384)
 notes=list(footnotes(s)); assert len(notes)==2
 for a,b,n in reversed(notes):
  r(s[a:b],'','editorial footnote '+('on the base letter' if 'aucune base' in n else 'on separability'),kind='structure',why='Absent from the exposé scan; correction evidence belongs in the ledger and the author erratum stays separate.')
 r(r'\underline P',r'\text{\uwave{P}}','opening representing letter',why='The printed underline is wavy.')
 r('en groupes.\nNotons','en groupes :\nNotons','opening paragraph punctuation',why='The enlarged scan has a colon after groupes.')
 r('jacobiennes généralisées de Rosenlicht',r'\uline{jacobiennes généralisées} de ROSENLICHT','generalized Jacobians typography',why='The two words are underlined and ROSENLICHT is in capitals.')
 r('suivantes : $X$ est propre et plat sur','suivantes : $X$ est \\uline{propre} et \\uline{plat} sur','existence conditions emphasis',why='Separate underlines under propre and plat.')
 r('et $X$ admet localement une section sur','et $X$ \\uline{admet localement une section sur}','section hypothesis emphasis',why='Underline ends before S.')
 span="pour éliminer\nles automorphismes d'un faisceau inversible $L$ sur $X$ en le munissant d'une\nsection marquée au-dessus de la section $s$"
 r(span,underline_prose(span),'rigidification emphasis',why='The prose is underlined; mathematical L/X/s are excluded from the prose underline.')
 r('$L$',r'$\text{\uwave{L}}$','invertible sheaf letter',why='L has its own short wavy underline.')
 r(r'\result{PROPOSITION}{3.1}',r'\result{PROPOSITION}{3, 1}','proposition number',why='Comma-numbered statement.')
 r('la proposition 3.1 ne','la proposition 3, 1 ne','proposition reference',why='Printed comma-numbered reference.')
 old='de type fini sur $S$, on ait\n\\[\n  f_{T*}(\\mathcal O_{X_T})=\\mathcal O_T\n\\]\n(si $f$ est propre et séparable, ou si $S$ est le'
 new='de type fini sur $S$, on ait $f_{T*}(\\mathcal O_{X_T})=\\mathcal O_T$ (si $f$ est propre et à\nfibres séparables ou si $S$ est le'
 r(old,new,'proposition hypothesis and parenthesis opening',kind='structure',why='The base-change equality is inline. The original says propre et à fibres séparables without a comma before ou; the later erratum wording had been merged into both sources and is removed.')
 r('De plus, on aura ici\n','De plus, on aura ici :\n','tangent display introduction',why='Printed colon.')
 r(r'F(I_A,\xi)=H^1(X_A,\mathcal O_{X_A}),',r'F(I_A,\xi)=H^1(X_A,\mathcal O_{X_A})','tangent display punctuation',why='No terminal comma; the degree 1 is correct here and retained in both layers.')
 r('qui est affine et plat sur $S$, et\ncommutatif.','qui est \\uline{affine et plat sur} $S$, et\n\\uline{commutatif}.','principal group hypotheses emphasis',why='The prose is underlined, with S outside.')
 span="La règle d'or à retenir, dans le contexte du présent"
 r(span,underline_prose(span),'last-line emphasis',why='The entire last printed line is underlined; continuation is on page 385.')
 s,_,_=page_text(rel,384)
 r(r'\mathcal O',r'\text{\uwave{O}}','structural sheaf letters',count=s.count(r'\mathcal O'),why='Short wavy underlines on all structural O letters, unlike plain topological ring O in the corollary.')
 if tree=='fr_printed':
  r('tout point de $S$ admet','tout point de $Y$ admet','remark base letter',why='The scan prints Y, although the base throughout this section is S.')
